package com.example.starter.observation;

/**
 * 维护窗口行类型：登记窗口或追加更正窗口。维护窗口只追加、不更新不删除。
 */
public enum MaintenanceWindowKind {
    /**
     * 登记窗口：站点首次登记的一个维护区间。
     */
    REGISTER,
    /**
     * 追加更正窗口：替换既有窗口时间区间，或撤回（retract）既有窗口；本身是一条新的不可变版本行。
     */
    CORRECTION
}

package com.example.starter.observation;

/**
 * 观测提交的处理状态。
 */
public enum SubmissionStatus {
    /**
     * 待合并：原始记录已保存，尚未进入冲突簇合并。
     */
    PENDING,
    /**
     * 待人工裁决：所属冲突簇只含受影响观测，自动合并判定为 REVIEW，等待人工裁决。
     */
    REVIEW,
    /**
     * 已并入观测版本：无论作为胜出内容还是被覆盖的簇成员，均不再参与后续合并。
     */
    CONSUMED
}

package com.example.starter.observation;

/**
 * 冲突簇合并状态。
 */
public enum ClusterMergeState {
    /**
     * 自动胜出：簇内至少一条未受影响观测，已自动选择胜出者并固化为观测版本。
     */
    AUTO_MERGED,
    /**
     * 待人工裁决：冲突簇只含 MAINTENANCE_AFFECTED 观测，不自动选择胜出者，等待人工裁决。
     */
    PENDING_MANUAL,
    /**
     * 已人工裁决：裁决人写入理由后选择了胜出提交（可为受影响观测），已固化为观测版本。
     */
    RESOLVED
}

