                MaintenanceWindowKind.valueOf(rs.getString("kind")),
                start == null ? null : start.toInstant(),
                end == null ? null : end.toInstant(),
                rs.getString("supersedes_window_id"),
                rs.getBoolean("retracted"),
                created.toInstant());
    };

