        @NotBlank @Size(max = 128) String windowId,
        @NotBlank @Size(max = 64) String stationId,
        @NotBlank @Size(max = 128) String supersedesWindowId,
        Instant startAtUtc,
        Instant endAtUtc,
        @NotNull Boolean retract) {
}

